import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry enum validation', () => {
  it('rejects values outside the declared enum specs/hal-engine-tool-input-validation/spec.md#3', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'ok');
    registry.register(
      {name: 'units', description: 'Units', inputSchema: {type: 'object', properties: {unit: {enum: ['metric']}}}},
      execute
    );
    const response = await registry.execute('units', {unit: 'imperial'});
    expect({result: response.result, calls: execute.mock.calls.length}).toEqual({
      result: expect.stringMatching(/unit.*allowed values/),
      calls: 0,
    });
  });
});
EOF
